110	/** Mocks the scroll container's native `scrollTo` (absent under jsdom), same technique as
111	 *  zimmProductCardMedia/index.test.tsx's own mockScrollTo. */
112	const mockScrollTo = (): ReturnType<typeof vi.fn> => {
113	  const scrollContainer = screen.getByTestId('card-media-scroll');
114	  const scrollTo = vi.fn();
115	  scrollContainer.scrollTo = scrollTo;
