224	describe('ZimmProductCard — exactly one real anchor regardless of variation', () => {
225	  test.each(['plp', 'home', 'wishlist'] as const)('variation=%s renders exactly one <a>', (variation) => {
226	    wrap(<ZimmProductCard {...buildCardProps(variation)} />);
227	    const links = screen.getAllByRole('link');
228	    expect(links).toHaveLength(1);
229	    expect(links[0]).toHaveAttribute('href', '/product/1');
230	  });
