233	/**
234	 * KNOWN LIMITATION — read before trusting these as proof of the real z-index layering.
235	 *
236	 * Every test below fires a click/keydown directly on the target control's own DOM node via
237	 * Testing Library. That proves the CALLBACK WIRING is correct: the right element calls the right
238	 * handler when it is actually interacted with. It does NOT prove that a real mouse click at that
239	 * screen position, in an actual browser, would land on that control rather than on the invisible
240	 * stretched-link `::after` overlay sitting over the whole card — jsdom performs no real layout,
241	 * paint, or hit-testing (no CSS cascade resolution, no stacking-context/z-index comparison, no
242	 * geometry at all); `fireEvent`/`user-event` dispatch straight to the node you name, bypassing
243	 * whatever a browser's hit-testing algorithm would actually resolve at that (x, y). The
244	 * `zimmProductCard.css.ts` recipe assertions further below prove the CSS this organism emits has
245	 * the right `position`/`z-index` values (verified by literally compiling it through this
246	 * project's real Stylis — see that describe block) — but going from "the right CSS values exist"
247	 * to "a real browser click lands on the right element" is exactly the gap a real-browser
248	 * (Playwright or manual) check is for. Treat this whole file as necessary, not sufficient, proof.
249	 */
250	describe('ZimmProductCard — every interactive control stays separately clickable (wiring only, see limitation above)', () => {
251	  test('the bag button fires onAddToBag independently of the name-link overlay (PLP)', async () => {
252	    const onAddToBag = vi.fn();
253	    const user = userEvent.setup();
254	    wrap(<ZimmProductCard {...buildCardProps('plp')} onAddToBag={onAddToBag} />);
255	    await user.click(screen.getByRole('button', { name: 'Add to bag' }));
256	    expect(onAddToBag).toHaveBeenCalledTimes(1);
257	  });
258	
259	  test('the carousel arrows fire independently of the name-link overlay when there is more than one image', async () => {
260	    const user = userEvent.setup();
261	    wrap(<ZimmProductCard {...buildCardProps('plp')} images={GALLERY} />);
262	    mockScrollTo();
263	    await user.click(screen.getByRole('button', { name: 'Next image' }));
264	    expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument();
265	  });
266	
267	  test('a size chip fires onSizeChipSelect independently of the name-link overlay (PLP)', async () => {
268	    const onSizeChipSelect = vi.fn();
269	    const user = userEvent.setup();
270	    wrap(<ZimmProductCard {...buildCardProps('plp')} sizeChipValues={SIZES} onSizeChipSelect={onSizeChipSelect} />);
271	    await user.click(screen.getByRole('radio', { name: 'S' }));
272	    expect(onSizeChipSelect).toHaveBeenCalledWith('s');
273	  });
274	
275	  test('the remove (close) button fires onRemove independently of the name-link overlay (Wishlist)', async () => {
276	    const onRemove = vi.fn();
277	    const user = userEvent.setup();
278	    wrap(<ZimmProductCard {...buildCardProps('wishlist')} onRemove={onRemove} />);
279	    const button = screen.getByRole('button', { name: 'Remove Natura Dress from wishlist' });
280	    await user.click(button);
281	    expect(onRemove).toHaveBeenCalledTimes(1);
282	  });
283	
284	  test('the bag button also fires onAddToBag on a Wishlist card, independently of the remove button', async () => {
285	    const onAddToBag = vi.fn();
286	    const user = userEvent.setup();
287	    wrap(<ZimmProductCard {...buildCardProps('wishlist')} onAddToBag={onAddToBag} />);
288	    await user.click(screen.getByRole('button', { name: 'Add to bag' }));
289	    expect(onAddToBag).toHaveBeenCalledTimes(1);
290	  });
291	
292	  test('the name link itself is still a real, working anchor to href, not swallowed by its own overlay', () => {
293	    wrap(<ZimmProductCard {...buildCardProps('plp')} />);
294	    expect(screen.getByRole('link', { name: 'Natura Dress' })).toHaveAttribute('href', '/product/1');
295	  });
296	});
