298	describe('ZimmProductCard — VARIATION_CONFIG drives composed-child props (a sample, not exhaustive — full matrix is Media/Content’s own test responsibility)', () => {
299	  test('home never renders the bag, attributes row or size chips', () => {
300	    wrap(<ZimmProductCard {...buildCardProps('home')} currentPrice="$100.00" />);
301	    expect(screen.queryByRole('button', { name: 'Add to bag' })).not.toBeInTheDocument();
302	    expect(document.querySelector('[data-card-slot="sizeChips"]')).not.toBeInTheDocument();
303	  });
304	
305	  test('wishlist renders the colour/size attributes row', () => {
306	    wrap(<ZimmProductCard {...buildCardProps('wishlist')} currentPrice="$100.00" />);
307	    expect(screen.getByTestId('card-content-attributes')).toBeInTheDocument();
308	  });
309	
310	  test('plp out-of-stock renders a disabled bag and a notify-me CTA', () => {
311	    const onNotifyMe = vi.fn();
312	    wrap(<ZimmProductCard {...buildCardProps('plp')} isUnavailable onNotifyMe={onNotifyMe} />);
313	    expect(screen.getByRole('button', { name: 'Add to bag' })).toBeDisabled();
314	    expect(screen.getByRole('button', { name: 'Notify me' })).toBeInTheDocument();
315	  });
