318	/**
319	 * Real-recipe assertions — bypasses the useMultiStyleConfig mock entirely, same technique as
320	 * zimmProductCardMedia/index.test.tsx's "Fix 1" block and
321	 * zimmProductCardContent/index.test.tsx's own real-recipe block. The component-level tests above
322	 * all render through the flat mock at the top of this file, which cannot see whether the real
323	 * recipe ever regresses the hover-reveal media query, the stretched-link overlay, or the z-index
324	 * lift on the interactive controls.
325	 *
326	 * These string keys were independently verified by compiling this exact recipe shape through
327	 * this project's own installed Stylis (v4.2.0 — the same engine Emotion/Chakra invoke at
328	 * runtime): the plain descendant selectors below resolve exactly as written, scoped under this
329	 * recipe's own generated class, with no comma-list scoping surprises.
330	 */
331	describe('ZimmProductCard — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
332	  const HOVER_CAPABLE_QUERY = '@media (hover: hover) and (pointer: fine)';
333	  const STRETCH_KEY = '[data-card-slot="content"] a::after';
334	  const CLOSE_LIFT_KEY = '[data-card-slot="close"]';
335	  const CAROUSEL_LIFT_KEY = '[data-card-slot="carousel"] button';
336	  const CONTENT_LIFT_KEY = '[data-card-slot="content"] button';
337	  const PRICE_KEY = '[data-card-slot="content"] [data-card-slot="price"]';
338	  const SIZE_CHIPS_KEY = '[data-card-slot="content"] [data-card-slot="sizeChips"]';
339	  const HOVER_PRICE_KEY = `&:hover ${PRICE_KEY}`;
340	  const HOVER_SIZE_CHIPS_KEY = `&:hover ${SIZE_CHIPS_KEY}`;
341	
342	  test('the stretched-link overlay is unconditional, absolutely positioned, and carries no z-index of its own', () => {
343	    const style = ZimmProductCardRecipe.baseStyle({});
344	    const root = style.root as Record<string, unknown>;
345	    const after = root[STRETCH_KEY] as Record<string, unknown>;
346	    expect(after.position).toBe('absolute');
347	    expect(after.inset).toBe(0);
348	    expect(Object.prototype.hasOwnProperty.call(after, 'zIndex')).toBe(false);
349	  });
350	
351	  test('every interactive-control selector is lifted above the overlay with position:relative + zIndex:1', () => {
352	    const style = ZimmProductCardRecipe.baseStyle({});
353	    const root = style.root as Record<string, unknown>;
354	    for (const key of [CLOSE_LIFT_KEY, CAROUSEL_LIFT_KEY, CONTENT_LIFT_KEY]) {
355	      const rule = root[key] as Record<string, unknown>;
356	      expect(rule.position).toBe('relative');
357	      expect(rule.zIndex).toBe(1);
358	    }
359	  });
360	
361	  test('root itself establishes the positioned ancestor the stretched-link overlay resolves against', () => {
362	    const style = ZimmProductCardRecipe.baseStyle({});
363	    expect((style.root as Record<string, unknown>).position).toBe('relative');
364	  });
365	
366	  test('home (hoverRevealsPrice): price is hidden by default and revealed only on hover, no size-selector rule at all', () => {
367	    const style = ZimmProductCardRecipe.baseStyle({ hoverRevealsPrice: true });
368	    const root = style.root as Record<string, unknown>;
369	    expect((root[PRICE_KEY] as Record<string, unknown>).display).toBe('none');
370	    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
371	    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).display).toBe('block');
372	    expect(root[SIZE_CHIPS_KEY]).toBeUndefined();
373	    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
374	  });
375	
376	  test('plp/wishlist (hoverHidesPrice + hoverRevealsSizeSelector): price visible by default, size-selector hidden by default, both swap on hover', () => {
377	    const style = ZimmProductCardRecipe.baseStyle({ hoverHidesPrice: true, hoverRevealsSizeSelector: true });
378	    const root = style.root as Record<string, unknown>;
379	    // No unconditional price rule — Content's own natural rendering already shows it by default.
380	    expect(root[PRICE_KEY]).toBeUndefined();
381	    expect((root[SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('none');
382	    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
383	    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).display).toBe('none');
384	    expect((hoverBlock[HOVER_SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('block');
385	  });
386	
387	  test('with every hover flag false/absent, no hover-reveal rule is emitted at all — a touch/no-hover pointer keeps the natural default permanently', () => {
388	    const style = ZimmProductCardRecipe.baseStyle({});
389	    const root = style.root as Record<string, unknown>;
390	    expect(root[PRICE_KEY]).toBeUndefined();
391	    expect(root[SIZE_CHIPS_KEY]).toBeUndefined();
392	    const hoverBlock = (root[HOVER_CAPABLE_QUERY] ?? {}) as Record<string, unknown>;
393	    expect(hoverBlock[HOVER_PRICE_KEY]).toBeUndefined();
394	    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
395	  });
396	});
