/**
 * Fix 1 (Scorer rework round 1) — DOM-level proof, not just an object-shape assertion. The
 * "real recipe assertions" block above proves this organism's OWN recipe object has the right
 * shape, but the actual bug was a CASCADE interaction between TWO separate recipes
 * (ZimmProductCardMedia's `close` part and this organism's `root` part) converging on the SAME
 * DOM node — that can only be proven by actually composing both recipes' real output through the
 * real Chakra/Emotion pipeline and reading the browser-resolved (here, jsdom-resolved) value back
 * via `getComputedStyle`, the same two real recipe modules the block above already imports
 * directly (bypassing the flat useMultiStyleConfig mock at the top of this file). `chakra` is
 * imported normally at the top of this file rather than via `vi.importActual` because the
 * `vi.mock('@chakra-ui/react', ...)` factory only overrides `useMultiStyleConfig` and spreads
 * `...actual` for everything else — `chakra` was never mocked, so it is already the real,
 * Emotion-backed factory and genuinely injects CSS into the jsdom document.
 *
 * This only asserts `position`/`top`/`right` — plain declarative property values, not real layout
 * geometry. Per this file's own "KNOWN LIMITATION" docblock (above the click-wiring describe
 * block) and `.claude/rules/testing.md`, jsdom performs no real layout/paint/hit-testing, so this
 * cannot prove a real mouse click lands on this button rather than some overlapping element —
 * only a real-browser/Playwright/manual check can prove that. It CAN correctly resolve which of
 * two competing same-property declarations wins a cascade by specificity, which is exactly what
 * this bug was and is what this test targets.
 */
describe('ZimmProductCard — Fix 1 (Scorer rework round 1): close button stays visually pinned', () => {
  test('the real close-button recipe, composed under the real organism root recipe in an actual rendered DOM node, resolves to position:absolute / top:0 / right:0 — not knocked into flow by the root’s lift rule', () => {
    const rootStyle = ZimmProductCardRecipe.baseStyle({
      hoverHidesPrice: true,
      hoverRevealsPrice: false,
      hoverRevealsSizeSelector: true,
    }).root;
    const closeStyle = ZimmProductCardMediaRecipe.baseStyle().close;

    // Reproduces the real app's exact shape: Media's own `close` part styles the button directly
    // (one generated class, applied via Media's own __css prop in its own file); this organism's
    // `root` recipe's `[data-card-slot="close"]` descendant+attribute selector is a SECOND,
    // higher-specificity rule reaching the same button from the organism's own generated class on
    // its ancestor `div`. Both are wired here via the real (unmocked) `chakra` factory, so the
    // actual Emotion CSS text these two recipes emit — and the actual cascade between them — is
    // what jsdom resolves, not a hand-simplified stand-in.
    const { container } = render(
      <chakra.div __css={rootStyle}>
        <chakra.button __css={closeStyle} data-card-slot="close">
          close
        </chakra.button>
      </chakra.div>,
    );

    const button = container.querySelector('[data-card-slot="close"]') as HTMLElement;
    const computed = window.getComputedStyle(button);
    expect(computed.position).toBe('absolute');
    expect(computed.top).toBe('0px');
    expect(computed.right).toBe('0px');
  });
});

/**
 * Fix 2 (Scorer rework round 1) — DOM-level proof that `:focus-within` on the card root actually
 * engages on a real focus event, not just that the recipe object carries the right string key
 * (already proven structurally in the "real recipe assertions" block above). Same real-`chakra` +
 * real-recipe composition technique as the Fix 1 block above, minimally extended with a plain
 * `[data-card-slot="content"]` wrapper and a focusable descendant button standing in for any of
 * the card's real interactive controls (bag button / name link / size chip) — the mechanism under
 * test is `:focus-within` bubbling from ANY descendant up to the organism's own root, not which
 * specific control receives focus.
 *
 * Per this file's own "KNOWN LIMITATION" docblock, jsdom does not implement real layout, paint or
 * hit-testing — but pseudo-class matching against a real DOM focus event, and resolving a plain
 * `display` declaration, are neither of those: this is meaningfully testable in a way the Fix 1
 * z-index/stacking question (proven instead via the object-shape assertions above) is not.
 */
describe('ZimmProductCard — Fix 2 (Scorer rework round 1): size chips reveal on keyboard focus, not just mouse hover', () => {
  test('focusing a descendant control inside the composed card reveals the size-chip slot via :focus-within on the card root, matching the existing :hover reveal', () => {
    const rootStyle = ZimmProductCardRecipe.baseStyle({
      hoverHidesPrice: true,
      hoverRevealsPrice: false,
      hoverRevealsSizeSelector: true,
    }).root;

    const { container } = render(
      <chakra.div __css={rootStyle}>
        <div data-card-slot="content">
          <button type="button">Add to bag</button>
          <div data-card-slot="sizeChips">size chips</div>
        </div>
      </chakra.div>,
    );

    const sizeChips = container.querySelector('[data-card-slot="sizeChips"]') as HTMLElement;
    // Before focus lands anywhere in the card: hidden by the unconditional
    // (outside-media-query) rule — the same default a touch/no-hover pointer sees permanently.
    expect(window.getComputedStyle(sizeChips).display).toBe('none');

    const bagButton = screen.getByRole('button', { name: 'Add to bag' });
    fireEvent.focus(bagButton);

    // :focus-within on the card ROOT (not on the size-chip wrapper itself, which would be
    // circular — an element that is display:none is unfocusable and unreachable by Tab) bubbles
    // from this descendant's focus state up to the root, revealing the size-chip slot exactly as
    // hovering the card would.
    expect(window.getComputedStyle(sizeChips).display).toBe('block');
  });
});

