464	 * imported normally at the top of this file rather than via `vi.importActual` because the
465	 * `vi.mock('@chakra-ui/react', ...)` factory only overrides `useMultiStyleConfig` and spreads
466	 * `...actual` for everything else — `chakra` was never mocked, so it is already the real,
467	 * Emotion-backed factory and genuinely injects CSS into the jsdom document.
468	 *
469	 * This only asserts `position`/`top`/`right` — plain declarative property values, not real layout
470	 * geometry. Per this file's own "KNOWN LIMITATION" docblock (above the click-wiring describe
471	 * block) and `.claude/rules/testing.md`, jsdom performs no real layout/paint/hit-testing, so this
472	 * cannot prove a real mouse click lands on this button rather than some overlapping element —
473	 * only a real-browser/Playwright/manual check can prove that. It CAN correctly resolve which of
474	 * two competing same-property declarations wins a cascade by specificity, which is exactly what
475	 * this bug was and is what this test targets.
476	 */
477	describe('ZimmProductCard — Fix 1 (Scorer rework round 1): close button stays visually pinned', () => {
478	  test('the real close-button recipe, composed under the real organism root recipe in an actual rendered DOM node, resolves to position:absolute / top:0 / right:0 — not knocked into flow by the root’s lift rule', () => {
479	    const rootStyle = ZimmProductCardRecipe.baseStyle({
480	      hoverHidesPrice: true,
481	      hoverRevealsPrice: false,
482	      hoverRevealsSizeSelector: true,
483	    }).root;
484	    const closeStyle = ZimmProductCardMediaRecipe.baseStyle().close;
485	
486	    // Reproduces the real app's exact shape: Media's own `close` part styles the button directly
487	    // (one generated class, applied via Media's own __css prop in its own file); this organism's
488	    // `root` recipe's `[data-card-slot="close"]` descendant+attribute selector is a SECOND,
489	    // higher-specificity rule reaching the same button from the organism's own generated class on
490	    // its ancestor `div`. Both are wired here via the real (unmocked) `chakra` factory, so the
491	    // actual Emotion CSS text these two recipes emit — and the actual cascade between them — is
492	    // what jsdom resolves, not a hand-simplified stand-in.
493	    const { container } = render(
494	      <chakra.div __css={rootStyle}>
495	        <chakra.button __css={closeStyle} data-card-slot="close">
496	          close
497	        </chakra.button>
498	      </chakra.div>,
499	    );
500	
501	    const button = container.querySelector('[data-card-slot="close"]') as HTMLElement;
502	    const computed = window.getComputedStyle(button);
503	    expect(computed.position).toBe('absolute');
504	    expect(computed.top).toBe('0px');
505	    expect(computed.right).toBe('0px');
506	  });
