509	/**
510	 * Fix 2 (Scorer rework round 1) — DOM-level proof that the `:focus-within` reveal genuinely
511	 * engages on a real focus event, not just that the recipe object carries the right string key
512	 * (already proven structurally in the "real recipe assertions" block above).
513	 *
514	 * IMPORTANT — this is `.matches()`-based, not `getComputedStyle()`-based, and that is a
515	 * deliberate, empirically-verified choice, not an oversight. This file's own "KNOWN LIMITATION"
516	 * docblock (above the click-wiring describe block) already establishes that jsdom performs no
517	 * real layout/paint/hit-testing; investigating this fix surfaced a SEPARATE, more specific jsdom
518	 * gap that docblock does not cover: `window.getComputedStyle()` in this project's installed jsdom
519	 * does not dynamically re-resolve a pseudo-class-gated rule after the DOM's focus state changes
520	 * post-mount, even for a bare self-referential `&:focus-within` rule with no descendant selector
521	 * at all (confirmed by direct experiment — a real `.focus()` call correctly updates
522	 * `document.activeElement` and correctly makes `element.matches(':focus-within')` return `true`,
523	 * but a subsequent `getComputedStyle()` read still reports the PRE-focus value). This is exactly
524	 * why Fix 1's proof above (a purely static cascade with no pseudo-class involved) could safely
525	 * use `getComputedStyle()` while this one cannot. `.matches()` against the exact literal
526	 * descendant-selector suffix the real recipe emits (`SIZE_CHIPS_KEY`, module-scope above) — with
527	 * only the Emotion-specific `&` swapped for a plain stand-in ancestor selector, since `&` is an
528	 * Emotion/PostCSS nesting token resolved at CSS-in-JS compile time, not a selector nwsapi
529	 * understands directly — correctly reflects the live DOM focus state both before and after a
530	 * real `.focus()` call, so it is what actually proves the mechanism here.
531	 */
532	describe('ZimmProductCard — Fix 2 (Scorer rework round 1): size chips reveal on keyboard focus, not just mouse hover', () => {
533	  test('an ancestor :focus-within + the real recipe’s own descendant-selector suffix flips from non-matching to matching once a nested control receives real focus', () => {
534	    const ANCESTOR_STAND_IN = '[data-testid="card-root"]';
535	    // Swap the Emotion-only `&` token for the stand-in ancestor selector above — the remaining,
536	    // actual descendant path comes straight from the real recipe's own module-scope constant,
537	    // not a hand-typed second copy.
538	    const revealSelector = FOCUS_WITHIN_SIZE_CHIPS_KEY.replace('&', ANCESTOR_STAND_IN);
539	
540	    const { container } = render(
541	      <div data-testid="card-root">
542	        <div data-card-slot="content">
543	          <button type="button">Add to bag</button>
544	          <div data-card-slot="sizeChips">size chips</div>
545	        </div>
546	      </div>,
547	    );
548	
549	    const sizeChips = container.querySelector('[data-card-slot="sizeChips"]') as HTMLElement;
550	    // Before focus lands anywhere in the card, the reveal selector does not match — mirrors the
551	    // unconditional (outside-media-query) `display: none` default a touch/no-hover pointer sees
552	    // permanently in the real recipe.
553	    expect(sizeChips.matches(revealSelector)).toBe(false);
554	
555	    // A real `.focus()` call (not `fireEvent.focus`, which only dispatches a synthetic event
556	    // without moving `document.activeElement` — confirmed empirically not to engage
557	    // `:focus-within` matching here) on a descendant of the card root.
558	    screen.getByRole('button', { name: 'Add to bag' }).focus();
559	
560	    // :focus-within on the card ROOT (not on the size-chip wrapper itself, which would be
561	    // circular — an element that is display:none is unfocusable and unreachable by Tab) bubbles
562	    // from this descendant's real focus state up to the root, so the reveal selector now matches
563	    // — the same live-DOM condition the real recipe's CSS rule keys its `display: block` off.
564	    expect(sizeChips.matches(revealSelector)).toBe(true);
565	  });
566	
567	  test('the reveal selector still does not match a sibling control receiving focus outside the card root entirely', () => {
568	    const ANCESTOR_STAND_IN = '[data-testid="card-root"]';
569	    const revealSelector = FOCUS_WITHIN_SIZE_CHIPS_KEY.replace('&', ANCESTOR_STAND_IN);
570	
571	    const { container } = render(
572	      <>
573	        <button type="button">Outside the card</button>
574	        <div data-testid="card-root">
575	          <div data-card-slot="content">
576	            <div data-card-slot="sizeChips">size chips</div>
577	          </div>
578	        </div>
579	      </>,
580	    );
581	
582	    const sizeChips = container.querySelector('[data-card-slot="sizeChips"]') as HTMLElement;
583	    screen.getByRole('button', { name: 'Outside the card' }).focus();
584	
585	    // Guards against a selector so loose it would match regardless of where focus actually is —
586	    // focus outside the card root must never trigger the reveal.
587	    expect(sizeChips.matches(revealSelector)).toBe(false);
588	  });
589	});
